  export type Result<O> =
    | { readonly ok: true; readonly value: O; readonly invocation: string; readonly costUsd: number; readonly model?: string }
    | { readonly ok: false; readonly error: string; readonly invocation: string; readonly costUsd: number; readonly model?: string };

  export type JobPoll<O> =
    | { readonly status: 'running' }
    | { readonly status: 'done'; readonly result: O }
    | { readonly status: 'failed'; readonly error: string };

  export interface Failed {
    readonly failed: string;
  }

  export interface InvocationContext {
    readonly attempt: string;
    readonly unit: string;
    readonly seq: number;
    readonly cancellation: Cancellation;
    workspace(runner: Runner): Promise<Workspace>;
  }

  export type Recovery<I> = 'rerun' | 'park' | Executable<I, boolean>;

  export type Recovered<O> =
    | { readonly finished: Result<O> }
    | { readonly rerun: true }
    | { readonly park: string };

  export interface Executable<I, O> extends ExecutableName {
    invoke(input: I, ctx: InvocationContext): Promise<Result<O>>;
    recover(input: I, ctx: InvocationContext): Promise<Recovered<O>>;
    locksFor?(input: I): readonly Lock[];
  }

  export interface ExternalJob<I, O> extends Executable<I, O> {
    readonly entity: 'job';
    readonly every: Interval;
    submit(input: I, ctx: InvocationContext): Promise<string>;
    poll(handle: string, ctx: InvocationContext): Promise<JobPoll<O>>;
  }

  export interface PendingView<T = unknown, S extends string = string> extends UnitView<T, S> {
    readonly waitedMs: number;
    is<T2, S2 extends string>(kind: Kind<T2, S2>): this is PendingView<T2, S2>;
  }

  export interface ActiveView<T = unknown, S extends string = string> extends UnitView<T, S> {
    readonly attempt: string;
    is<T2, S2 extends string>(kind: Kind<T2, S2>): this is ActiveView<T2, S2>;
  }

  export interface WaitingView<T = unknown, S extends string = string> extends UnitView<T, S> {
    readonly attempt?: string;
    readonly waitingOn?: 'halt' | 'timer' | 'job' | 'children' | 'state';
    is<T2, S2 extends string>(kind: Kind<T2, S2>): this is WaitingView<T2, S2>;
  }

  export interface AccountView {
    readonly account: Account;
    readonly pool: string;
    readonly eligible: boolean;
    readonly share: number;
    readonly usedShare: number;
    readonly windowEndsAt?: Date;
  }

  export type PolicyDomain = 'model' | 'account' | 'scheduler' | 'retry' | 'rule';

  export interface Policy<C, D> extends Named {
    readonly entity: 'policy';
    readonly decides: PolicyDomain;
    decide(context: C): D;
  }

  export interface ModelChoice {
    readonly kind: KindRef;
    readonly seat: SeatRef;
    readonly metrics: Metrics;
  }

  export interface AccountChoice {
    readonly accounts: readonly AccountView[];
  }

  export interface SchedulerView {
    readonly now: Date;
    readonly pending: readonly PendingView[];
    readonly active: readonly ActiveView[];
    readonly waiting: readonly WaitingView[];
    readonly metrics: Metrics;
  }

  export interface ScheduleDecision {
    readonly start: readonly PendingView[];
    readonly preempt?: readonly ActiveView[];
  }

  export interface RetryView {
    readonly retriesUsed: number;
  }
  export type RetryDecision = { readonly retryInMs: number } | 'stop';

  export interface Offer {
    readonly invocation: string;
    readonly seat: string;
    readonly output: unknown;
  }

  export interface HaltView {
    readonly id: string;
    readonly attempt: string;
    readonly unit: string;
    readonly halt: string;
    readonly occurrence: number;
    readonly show: string;
    readonly about: unknown;
    readonly offers: readonly Offer[];
    readonly raised: Date;
  }

  export interface ControlApi {
    readonly work: {
      list(query: { readonly lane?: LaneName; readonly position?: Position | readonly Position[] }): Promise<readonly UnitRecord[]>;
      get(lane: LaneName, key: string): Promise<UnitRecord | undefined>;
      create<T, S extends string>(lane: LaneRef<T, S>, data: T, key?: string): Promise<string>;
      update<T, S extends string>(lane: LaneRef<T, S>, key: string, patch: Partial<T>): Promise<void>;
      move<T, S extends string>(lane: LaneRef<T, S>, key: string, state: S, reason: string): Promise<void>;
    };
    readonly halts: {
      list(halt?: HaltName): Promise<readonly HaltView[]>;
      resolve<D, C>(halt: HaltRef<D, C>, id: string, decision: D, credited?: readonly string[]): Promise<void>;
    };
    readonly memory: {
      list(journal: JournalRef): Promise<readonly MemoryItem[]>;
      write(journal: JournalRef, item: MemoryDraft): Promise<string>;
      accept(journal: JournalRef, id: string): Promise<void>;
      merge(journal: JournalRef, ids: readonly string[], into: MemoryDraft): Promise<string>;
      drop(journal: JournalRef, id: string): Promise<void>;
    };
    readonly telemetry: {
      readonly metrics: Metrics;
      report<R>(report: ReportRef<R>): Promise<R>;
      entries(query: { readonly filter: EntryFilter; readonly since?: Date }): Promise<readonly LedgerEntry[]>;
    };
    readonly accounts: {
      list(pool?: PoolRef): Promise<readonly AccountView[]>;
      setShare(pool: PoolRef, account: Account, share: number): Promise<void>;
    };
    readonly custom: {
      invoke(operation: Operation, input: unknown): Promise<Result<unknown>>;
    };
  }

  export interface Registry {
    lane(name: string): LaneRef<unknown, string> | undefined;
    halt(name: string): HaltRef<unknown, unknown> | undefined;
    journal(name: string): JournalRef | undefined;
    report(name: string): ReportRef<ReportShape> | undefined;
    pool(name: string): PoolRef | undefined;
    account(name: string): Account | undefined;
    operation(name: string): Operation | undefined;
  }

  export type ControlMethod =
    | 'work.list' | 'work.get' | 'work.create' | 'work.update' | 'work.move'
    | 'halts.list' | 'halts.resolve'
    | 'memory.list' | 'memory.write' | 'memory.accept' | 'memory.merge' | 'memory.drop'
    | 'telemetry.metrics' | 'telemetry.report' | 'telemetry.entries'
    | 'accounts.list' | 'accounts.setShare'
    | 'custom.invoke';

  export interface Operation extends Named {
    readonly entity: 'operation';
    readonly methods: readonly ControlMethod[];
    readonly halts?: readonly HaltName[];
    readonly executable?: ExecutableName;
  }

  export interface Client extends Named {
    readonly grants: readonly Operation[];
    serve(api: ControlApi, registry: Registry): Promise<Stoppable>;
  }

  export interface HarnessView {
    readonly harness: string;
    units(query: { readonly kind?: string; readonly position?: Position | readonly Position[] }): Promise<readonly UnitRecord[]>;
    readonly metrics: Metrics;
    readonly reports: readonly ReportRef<ReportShape>[];
  }

  export interface Observer extends Named {
    notify(entry: LedgerEntry, view: HarnessView): Promise<void>;
  }

  export interface Running {
    readonly run: string;
    readonly control: ControlApi;
    stop(): Promise<void>;
  }
}
